export const code = async (inputs) => {
if (typeof inputs.scope !== 'string' || inputs.scope.trim().length === 0 || inputs.scope.length > 4000) {
  throw new Error('scope must be non-empty text of at most 4000 characters.');
}
const finiteNonnegative = (name) => {
  const value = inputs[name];
  if (typeof value !== 'number' || !Number.isFinite(value) || value < 0) {
    throw new Error(`${name} must be a finite number greater than or equal to zero.`);
  }
  return value;
};
const monthlyValue = finiteNonnegative('hoursPerWeek') * finiteNonnegative('hourlyRate') * 4;
if (!Number.isFinite(monthlyValue)) {
  throw new Error('The calculated monthly value must be finite. Use smaller input values.');
}
return { scope: inputs.scope, monthlyValue };
};
